import numpy as np

def hessian(f, x, h=1e-5):
    n = x.size; H = np.zeros((n, n))
    for i in range(n):
        for j in range(n):
            ei, ej = np.eye(n)[i] * h, np.eye(n)[j] * h
            H[i, j] = (f(x+ei+ej) - f(x+ei-ej) - f(x-ei+ej) + f(x-ei-ej)) / (4*h*h)
    return H

A = np.array([[2.0, 0.5], [0.5, 1.0]]); b = np.array([1.0, -1.0])
for name, f in [("quad", lambda w: 0.5*w@A@w - b@w),
                ("saddle", lambda w: w[0]**2 - w[1]**2)]:
    w = np.linalg.eigvalsh(hessian(f, np.array([0.3, -0.2])))
    print(f"{name:7s} eigvals={np.round(w, 4)}  convex={w.min() >= -1e-6}")
